import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyCuDan = () => {
    const [selectedRoom, setSelectedRoom] = useState(null);

    const databaseResidents = {}; 

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const getResidentInfo = (roomId) => {
        return databaseResidents[roomId] || {
            name: "Chưa có dữ liệu",
            gender: "---",
            phone: "---",
            members: 0,
            parking: "---"
        };
    };

    const info = selectedRoom ? getResidentInfo(selectedRoom) : null;

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            <div style={{ padding: '20px', color: '#fff' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý cư dân</h2>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG */}
                <div style={{ 
                    width: '210px', 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', 
                    alignContent: 'flex-start', 
                    overflowY: 'auto',
                    padding: '12px',
                    backgroundColor: 'rgba(255,255,255,0.1)',
                    borderRadius: '20px',
                    border: '1px solid rgba(255,255,255,0.1)'
                }}>
                    {allRooms.map(room => (
                        <div 
                            key={room} 
                            onClick={() => setSelectedRoom(room)}
                            style={{ 
                                background: selectedRoom === room ? '#8b5e5e' : 'white', 
                                color: selectedRoom === room ? 'white' : '#333',
                                padding: '8px 0', 
                                borderRadius: '8px', 
                                textAlign: 'center', 
                                fontSize: '11px', 
                                fontWeight: 'bold', 
                                cursor: 'pointer',
                                transition: '0.2s',
                                border: '1px solid #ddd'
                            }}
                        >
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: CHI TIẾT CƯ DÂN (NỀN TRẮNG CHỮ ĐEN) */}
                <div style={{ 
                    flex: 1, 
                    backgroundColor: '#ffffff', // Nền trắng đặc hoàn toàn
                    borderRadius: '25px', 
                    padding: '40px',
                    display: 'flex',
                    flexDirection: 'column',
                    color: '#333', // Chữ đen/xám đậm để dễ nhìn
                    boxShadow: '0 10px 30px rgba(0,0,0,0.2)' // Đổ bóng tạo độ nổi
                }}>
                    {selectedRoom ? (
                        <div style={{ animation: 'fadeIn 0.4s ease-out' }}>
                            <h1 style={{ 
                                fontSize: '50px', 
                                margin: '0 0 30px 0', 
                                color: '#8b5e5e', // Màu tiêu đề trùng với màu chủ đạo
                                borderBottom: '2px solid #eee', 
                                paddingBottom: '15px',
                                fontWeight: 'bold'
                            }}>
                                PHÒNG: {selectedRoom}
                            </h1>

                            <div style={{ display: 'flex', flexDirection: 'column', gap: '22px', fontSize: '18px' }}>
                                <div style={{ display: 'flex' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#666' }}>Tên chủ phòng:</span>
                                    <span style={{ fontWeight: '600' }}>{info.name}</span>
                                </div>
                                <div style={{ display: 'flex' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#666' }}>Giới tính:</span>
                                    <span>{info.gender}</span>
                                </div>
                                <div style={{ display: 'flex' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#666' }}>Liên hệ (SĐT):</span>
                                    <span>{info.phone}</span>
                                </div>
                                <div style={{ display: 'flex' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#666' }}>Số lượng thành viên:</span>
                                    <span>{info.members} người</span>
                                </div>
                                <div style={{ display: 'flex' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#666' }}>Bãi đỗ xe:</span>
                                    <span>{info.parking}</span>
                                </div>
                            </div>

                            {/* Nút thao tác thêm nếu cần */}
                            <div style={{ marginTop: '50px', display: 'flex', gap: '15px' }}>
                                <button style={{ 
                                    padding: '12px 25px', borderRadius: '10px', border: 'none', 
                                    backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer' 
                                }}>
                                    Cập nhật thông tin
                                </button>
                                <button style={{ 
                                    padding: '12px 25px', borderRadius: '10px', border: '1px solid #ddd', 
                                    backgroundColor: '#fff', color: '#333', fontWeight: 'bold', cursor: 'pointer' 
                                }}>
                                    Lịch sử thanh toán
                                </button>
                            </div>
                        </div>
                    ) : (
                        <div style={{ 
                            flex: 1, 
                            display: 'flex', 
                            justifyContent: 'center', 
                            alignItems: 'center', 
                            color: '#999', 
                            fontSize: '20px', 
                            fontStyle: 'italic' 
                        }}>
                            Chọn một phòng để hiển thị thông tin cư dân...
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default QuanLyCuDan;
